import{_ as r,o as a,c as o,ag as n}from"./chunks/framework.CAXxHpAX.js";const u=JSON.parse('{"title":"01 操作系统概述","description":"","frontmatter":{},"headers":[],"relativePath":"操作系统/01_操作系统概述.md","filePath":"操作系统/01_操作系统概述.md","lastUpdated":1777091574000}'),l={name:"操作系统/01_操作系统概述.md"};function s(i,t,e,d,h,g){return a(),o("div",null,[...t[0]||(t[0]=[n('<h1 id="_01-操作系统概述" tabindex="-1">01 操作系统概述 <a class="header-anchor" href="#_01-操作系统概述" aria-label="Permalink to &quot;01 操作系统概述&quot;">​</a></h1><blockquote><p>本章是操作系统的入门章节，主要考查操作系统的基本概念、特征、功能以及运行环境。以选择题为主，但系统调用与中断机制是理解后续所有章节的基础。</p></blockquote><h2 id="一、操作系统的概念" tabindex="-1">一、操作系统的概念 <a class="header-anchor" href="#一、操作系统的概念" aria-label="Permalink to &quot;一、操作系统的概念&quot;">​</a></h2><p>计算机系统自下而上可大致分为：<strong>硬件 → 操作系统 → 应用程序 → 用户</strong>。</p><p>操作系统 (Operating System) 是指<strong>控制和管理整个计算机系统的硬件与软件资源，合理地组织、调度计算机的工作与资源的分配</strong>，进而为用户和其他软件<strong>提供方便接口与环境的程序集合</strong>，操作系统是计算机系统中<strong>最基本的系统软件</strong>。</p><h2 id="二、操作系统的特征" tabindex="-1">二、操作系统的特征 <a class="header-anchor" href="#二、操作系统的特征" aria-label="Permalink to &quot;二、操作系统的特征&quot;">​</a></h2><p>操作系统有四个基本特征，其中<strong>并发和共享是两个最基本的特征</strong>，二者互为存在条件。</p><h3 id="_2-1-并发-concurrence" tabindex="-1">2.1 并发 (Concurrence) <a class="header-anchor" href="#_2-1-并发-concurrence" aria-label="Permalink to &quot;2.1 并发 (Concurrence)&quot;">​</a></h3><p>并发是指<strong>两个或多个事件在同一时间间隔内发生</strong>。</p><ul><li><strong>并发</strong>：同一时间<strong>间隔</strong>（一段时间内），宏观上多道程序同时执行，微观上分时交替执行</li><li><strong>并行</strong>：同一时<strong>刻</strong>，需要多处理器硬件支持</li></ul><div class="important custom-block github-alert"><p class="custom-block-title">并发 vs 并行</p><p>并发是&quot;一段时间内&quot;的宏观同时，并行是&quot;同一时刻&quot;的真正同时。单 CPU 系统中各进程只能并发执行，不能并行。</p></div><h3 id="_2-2-共享-sharing" tabindex="-1">2.2 共享 (Sharing) <a class="header-anchor" href="#_2-2-共享-sharing" aria-label="Permalink to &quot;2.2 共享 (Sharing)&quot;">​</a></h3><p>资源共享是指<strong>系统中的资源可供内存中多个并发执行的进程共同使用</strong>。</p><ul><li><strong>互斥共享</strong>：一段时间内<strong>只允许一个进程访问</strong>该资源（临界资源/独占资源）</li><li><strong>同时访问</strong>：宏观上允许多个进程&quot;同时&quot;访问（微观上交替访问），如磁盘</li></ul><h3 id="_2-3-虚拟-virtual" tabindex="-1">2.3 虚拟 (Virtual) <a class="header-anchor" href="#_2-3-虚拟-virtual" aria-label="Permalink to &quot;2.3 虚拟 (Virtual)&quot;">​</a></h3><p>虚拟是指<strong>把一个物理上的实体变为若干逻辑上的对应物</strong>。</p><ul><li><strong>虚拟处理器</strong>（时分复用）：利用多道程序设计技术，将一个物理 CPU 虚拟为多个逻辑 CPU</li><li><strong>虚拟存储器</strong>（空分复用）：从逻辑上扩充存储器容量</li><li><strong>虚拟设备</strong>：将一台物理 I/O 设备虚拟为多台逻辑设备（如 SPOOLing 技术）</li></ul><h3 id="_2-4-异步-asynchronism" tabindex="-1">2.4 异步 (Asynchronism) <a class="header-anchor" href="#_2-4-异步-asynchronism" aria-label="Permalink to &quot;2.4 异步 (Asynchronism)&quot;">​</a></h3><p>多道程序环境下，进程的执行<strong>不是一贯到底的</strong>，而是走走停停、以<strong>不可预知</strong>的速度向前推进。</p><div class="warning custom-block github-alert"><p class="custom-block-title">异步性要求</p><p>只要<strong>运行环境相同</strong>，操作系统就必须保证多次运行进程后都能获得<strong>相同的结果</strong>。</p></div><h2 id="三、操作系统的目标和功能" tabindex="-1">三、操作系统的目标和功能 <a class="header-anchor" href="#三、操作系统的目标和功能" aria-label="Permalink to &quot;三、操作系统的目标和功能&quot;">​</a></h2><h3 id="_3-1-系统资源的管理者" tabindex="-1">3.1 系统资源的管理者 <a class="header-anchor" href="#_3-1-系统资源的管理者" aria-label="Permalink to &quot;3.1 系统资源的管理者&quot;">​</a></h3><table tabindex="0"><thead><tr><th>管理功能</th><th>主要内容</th></tr></thead><tbody><tr><td><strong>处理机管理</strong></td><td>进程控制、进程同步、进程通信、死锁处理、处理机调度</td></tr><tr><td><strong>存储器管理</strong></td><td>内存分配与回收、地址映射、内存保护与共享、内存扩充</td></tr><tr><td><strong>文件管理</strong></td><td>文件存储空间管理、目录管理、文件读写管理和保护</td></tr><tr><td><strong>设备管理</strong></td><td>缓冲管理、设备分配和回收、设备处理、虚拟设备</td></tr></tbody></table><h3 id="_3-2-用户与硬件之间的接口" tabindex="-1">3.2 用户与硬件之间的接口 <a class="header-anchor" href="#_3-2-用户与硬件之间的接口" aria-label="Permalink to &quot;3.2 用户与硬件之间的接口&quot;">​</a></h3><ul><li><strong>命令接口</strong>： <ul><li>联机命令接口（交互式）：用户通过终端输入命令，适用于分时/实时系统</li><li>脱机命令接口（批处理）：用户事先编写作业操作说明书，如 <code>.bat</code> 文件</li></ul></li><li><strong>程序接口</strong>：由<strong>系统调用</strong>（广义指令）组成，用户只能通过程序间接使用</li></ul><div class="important custom-block github-alert"><p class="custom-block-title">GUI 不属于操作系统</p><p>图形接口最终通过调用<strong>程序接口</strong>（系统调用）实现。严格来说 GUI 不是操作系统的一部分，但 GUI 调用的系统调用是。</p></div><h3 id="_3-3-扩充机器" tabindex="-1">3.3 扩充机器 <a class="header-anchor" href="#_3-3-扩充机器" aria-label="Permalink to &quot;3.3 扩充机器&quot;">​</a></h3><p>没有任何软件支持的计算机称为<strong>裸机</strong>。覆盖了操作系统软件的机器称为<strong>扩充机器</strong>或<strong>虚拟机</strong>。</p><h2 id="四、操作系统的发展与分类" tabindex="-1">四、操作系统的发展与分类 <a class="header-anchor" href="#四、操作系统的发展与分类" aria-label="Permalink to &quot;四、操作系统的发展与分类&quot;">​</a></h2><h3 id="_4-1-手工操作阶段" tabindex="-1">4.1 手工操作阶段 <a class="header-anchor" href="#_4-1-手工操作阶段" aria-label="Permalink to &quot;4.1 手工操作阶段&quot;">​</a></h3><ul><li>无操作系统</li><li>用户独占全机，资源利用率低</li><li>CPU 等待手工操作，CPU 利用率低</li></ul><h3 id="_4-2-批处理阶段" tabindex="-1">4.2 批处理阶段 <a class="header-anchor" href="#_4-2-批处理阶段" aria-label="Permalink to &quot;4.2 批处理阶段&quot;">​</a></h3><p><strong>单道批处理系统</strong>：</p><ul><li>特征：自动性、顺序性、单道性</li><li>内存中仅一道程序，CPU 遇 I/O 请求时等待</li></ul><p><strong>多道批处理系统</strong>：</p><ul><li>多道程序<strong>同时驻留内存</strong>，<strong>宏观并行、微观串行</strong></li><li>优点：资源利用率高、系统吞吐量大</li><li>缺点：用户响应时间长、不提供人机交互</li></ul><h3 id="_4-3-分时操作系统" tabindex="-1">4.3 分时操作系统 <a class="header-anchor" href="#_4-3-分时操作系统" aria-label="Permalink to &quot;4.3 分时操作系统&quot;">​</a></h3><ul><li>多用户通过终端共享主机</li><li><strong>时间片轮转</strong>方式为各用户服务</li><li>特征：同时性、交互性、独立性、及时性</li></ul><h3 id="_4-4-实时操作系统" tabindex="-1">4.4 实时操作系统 <a class="header-anchor" href="#_4-4-实时操作系统" aria-label="Permalink to &quot;4.4 实时操作系统&quot;">​</a></h3><ul><li><strong>硬实时</strong>：必须绝对在规定时刻完成（如飞行控制）</li><li><strong>软实时</strong>：偶尔违反时限不会永久损害（如订票系统）</li><li>主要特点：<strong>及时性和可靠性</strong></li></ul><h2 id="五、操作系统的运行环境" tabindex="-1">五、操作系统的运行环境 <a class="header-anchor" href="#五、操作系统的运行环境" aria-label="Permalink to &quot;五、操作系统的运行环境&quot;">​</a></h2><h3 id="_5-1-运行机制" tabindex="-1">5.1 运行机制 <a class="header-anchor" href="#_5-1-运行机制" aria-label="Permalink to &quot;5.1 运行机制&quot;">​</a></h3><ul><li><strong>特权指令</strong>：不允许用户直接使用的指令（如 I/O 指令、置中断指令）</li><li><strong>非特权指令</strong>：用户程序可以使用的指令</li></ul><p>两种处理器状态：</p><table tabindex="0"><thead><tr><th></th><th>核心态（管态）</th><th>用户态（目态）</th></tr></thead><tbody><tr><td>可执行指令</td><td>特权 + 非特权</td><td>仅非特权</td></tr><tr><td>运行程序</td><td>系统内核程序</td><td>用户应用程序</td></tr></tbody></table><h3 id="_5-2-内核的功能" tabindex="-1">5.2 内核的功能 <a class="header-anchor" href="#_5-2-内核的功能" aria-label="Permalink to &quot;5.2 内核的功能&quot;">​</a></h3><p>内核是计算机上配置的<strong>底层软件</strong>，是计算机功能的延伸：</p><ol><li><strong>时钟管理</strong>：提供标准系统时间，实现进程切换</li><li><strong>中断机制</strong>：操作系统各项操作的基础，现代操作系统是<strong>靠中断驱动的软件</strong></li><li><strong>原语</strong>：最接近硬件、具有原子性的操作，不可被中断</li><li><strong>系统控制的数据结构及处理</strong>：进程管理、存储器管理、设备管理</li></ol><h3 id="_5-3-中断和异常" tabindex="-1">5.3 中断和异常 <a class="header-anchor" href="#_5-3-中断和异常" aria-label="Permalink to &quot;5.3 中断和异常&quot;">​</a></h3><ul><li><strong>中断（外中断）</strong>：来自 CPU 执行<strong>指令以外</strong>的事件（如 I/O 中断、时钟中断）</li><li><strong>异常（内中断）</strong>：源自 CPU 执行<strong>指令内部</strong>的事件（如非法操作码、缺页、陷入指令）</li></ul><div class="important custom-block github-alert"><p class="custom-block-title">用户态 → 核心态的唯一途径</p><p>CPU 运行用户程序时，进入核心态的<strong>唯一途径</strong>是通过<strong>中断或异常</strong>。核心态 → 用户态由特权指令（中断返回指令）实现。</p></div><p>中断处理流程：关中断 → 保存断点（硬件） → 引出中断服务程序 → 保存现场和屏蔽字 → 开中断 → 执行中断服务 → 关中断 → 恢复现场和屏蔽字 → 开中断、中断返回</p><h3 id="_5-4-系统调用" tabindex="-1">5.4 系统调用 <a class="header-anchor" href="#_5-4-系统调用" aria-label="Permalink to &quot;5.4 系统调用&quot;">​</a></h3><p>系统调用是指<strong>用户在程序中调用操作系统所提供的一些子功能</strong>，是特殊的公共子程序，<strong>运行在核心态</strong>。</p><p>系统调用按功能分为：</p><table tabindex="0"><thead><tr><th>类型</th><th>功能举例</th></tr></thead><tbody><tr><td>设备管理</td><td>设备请求/释放/启动</td></tr><tr><td>文件管理</td><td>文件读/写/创建/删除</td></tr><tr><td>进程控制</td><td>进程创建/撤销/阻塞/唤醒</td></tr><tr><td>进程通信</td><td>消息传递/信号传递</td></tr><tr><td>内存管理</td><td>内存分配/回收</td></tr></tbody></table><div class="warning custom-block github-alert"><p class="custom-block-title">访管指令 (trap)</p><p>用户通过<strong>陷入指令</strong>（访管指令）来调用系统调用。访管指令<strong>只能在用户态使用</strong>，它本身<strong>不是特权指令</strong>。</p></div><h2 id="六、大内核与微内核" tabindex="-1">六、大内核与微内核 <a class="header-anchor" href="#六、大内核与微内核" aria-label="Permalink to &quot;六、大内核与微内核&quot;">​</a></h2><table tabindex="0"><thead><tr><th></th><th>大内核</th><th>微内核</th></tr></thead><tbody><tr><td>设计思想</td><td>操作系统主要功能模块都在内核中</td><td>只保留最基本的功能在内核</td></tr><tr><td>优点</td><td><strong>高性能</strong></td><td>结构清晰，方便维护</td></tr><tr><td>缺点</td><td>内核庞大，结构混乱，难以维护</td><td>需频繁切换态，<strong>性能较低</strong></td></tr></tbody></table><hr><div class="important custom-block github-alert"><p class="custom-block-title">考点提示</p><p>本章以<strong>选择题</strong>为主，重点考查：四大特征的辨析（并发 vs 并行、互斥共享 vs 同时共享）、中断与异常的区分、用户态与核心态的转换机制、系统调用的概念。</p></div>',61)])])}const b=r(l,[["render",s]]);export{u as __pageData,b as default};
